/**
 * fixtures-live.test.ts — the H-24 REFRESHED-FIXTURE lane (the V-15 law
 * mechanized: the contract pins verify against RECORDED live-wire
 * bodies, so a fixture cannot fossilize into the V-24 fiction class).
 *
 * The recording (fixtures-live.gen.ts) is GENERATED by
 * scripts/a1/fixture-refresh.mjs (the record mode on the H-23
 * instrument family) — every body is a verbatim live-engine response
 * on the routes the adapter consumes. This lane runs each body through
 * assertContract: pin-vs-live drift REDDENS with the dotted path
 * (a drift is a ticket, never silent).
 *
 * The env override (FIXTURES_LIVE_PATH) is the H-24 GATE's lane: the
 * paired A/B harness records from a DELIBERATELY MUTATED stub engine
 * and re-runs THIS lane against that recording — the refreshed lane
 * must redden where the stale canned-fixture lane stays green (the
 * false-confidence delta, directly measured).
 *
 * Refresh-then-build (the H-24 SHOULD law): regenerate the recording
 * at every fixture-consuming ticket's open. A stale recording (old
 * capturedAt) still pins — the refresh cadence is the operator's law,
 * not a test-time failure — but the capturedAt is printed on every
 * run so staleness is visible, never silent.
 */
import { test, expect } from "bun:test";
import { assertContract, CONTRACT_FIXTURES } from "./contract.js";
import { mapRuns } from "./rest-adapter.js";
import type { ContractEndpoint } from "./contract.js";

const mod = await import(
  process.env.FIXTURES_LIVE_PATH
    ?? new URL("./fixtures-live.gen.ts", import.meta.url).href
);
const REC = mod.FIXTURES_LIVE as {
  captured: boolean;
  provenance?: { capturedAt?: string; engineVersion?: string | null; markerTitle?: string | null };
  endpoints: Record<string, { route: string; status: number; body: unknown }>;
};

/** The recorded GET lane: one assertContract per read endpoint. The
 *  write-path shapes (create/delete responses) assert their own pins. */
const READ_PINS: Array<[string, ContractEndpoint]> = [
  ["overview", "overview"],
  ["automations", "automations"],
  ["runs", "runs"],
  ["dreams", "dreams"],
  ["notes", "notes"],
  ["memory", "memory"],
  ["memory-health", "memory-health"],
  ["spend", "spend"],
];

if (!REC.captured) {
  // The loud skip: a recording that was never made is a NAMED gap,
  // never a silent pass (the honest-empty law).
  test("fixtures-live: NO RECORDING — run scripts/a1/fixture-refresh.mjs", () => {
    expect(true).toBe(true);
  });
  console.warn(
    "fixtures-live: FIXTURES_LIVE.captured is false — the refreshed lane is INACTIVE. " +
    "Run: node scripts/a1/fixture-refresh.mjs  (the refresh-then-build law, H-24)",
  );
} else {
  console.log(
    `fixtures-live: recording captured ${REC.provenance?.capturedAt ?? "?"} ` +
    `from ${REC.provenance?.engineVersion ?? "?"} (marker: ${REC.provenance?.markerTitle ?? "none"})`,
  );

  test("the recording covers every read endpoint the adapter consumes", () => {
    for (const [key] of READ_PINS) {
      expect(REC.endpoints[key], `missing recorded endpoint "${key}" — re-run the refresh`).toBeDefined();
    }
  });

  for (const [key, endpoint] of READ_PINS) {
    test(`REFRESHED PIN — ${key} (${REC.endpoints[key]?.route}): the recorded live body passes assertContract`, () => {
      assertContract(endpoint, REC.endpoints[key].body);
    });
  }

  test("the marker lifecycle write shapes pin (create + delete responses)", () => {
    const create = REC.endpoints["create-automation"];
    if (create) assertContract("single-automation", create.body);
    // DELETE answers {ok: true} — no contract endpoint; the status pin:
    const del = REC.endpoints["delete-automation"];
    if (del) expect(del.status).toBe(200);
  });

  test("the recorded runs rows map with RAW ids passed through (the V-24 law)", () => {
    const body = REC.endpoints["runs"].body as { runs: unknown[] };
    const mapped = mapRuns(body.runs);
    for (const r of mapped) {
      // The raw-passthrough law: a string wire id stays a string; a
      // numeric wire id stays numeric — never Number()-coerced (the
      // uuid coercion class is V-24 fiction #1).
      expect(typeof r.id === "string" || typeof r.id === "number").toBe(true);
    }
  });

  test("the marker automation row is engine-native snake_case (the refresh caught a real row, not a fixture echo)", () => {
    const body = REC.endpoints["automations"].body as { automations: Record<string, unknown>[] };
    const marker = body.automations.find(
      (a) => a.title === REC.provenance?.markerTitle,
    );
    expect(marker, "the marker row must be present in the recording (unless --no-marker was used)").toBeDefined();
    if (marker) {
      // The engine-native wire is snake_case with a string id — the
      // fixture lane's numeric-id camelCase rows are the OTHER lane.
      expect(typeof marker.id).toBe("string");
      expect(marker).toHaveProperty("schedule_kind");
      expect(marker).toHaveProperty("lifecycle");
    }
  });

  // The fossil detector (informational, never a hard fail): the
  // top-level key-set diff between the canned fixtures and the
  // recorded wire — the V-24 fiction classes become VISIBLE here.
  test("the shape-diff receipt: canned-vs-live key sets printed (the fossil detector)", () => {
    const diffs: string[] = [];
    const cannedKeys = (o: unknown) => (Array.isArray(o) && o[0] && typeof o[0] === "object"
      ? Object.keys(o[0]).sort().join(",")
      : typeof o === "object" && o !== null
        ? Object.keys(o).sort().join(",")
        : String(o));
    const pairs: Array<[string, unknown, unknown]> = [
      ["runs-row", CONTRACT_FIXTURES.runs[0], (REC.endpoints["runs"].body as { runs: unknown[] }).runs?.[0]],
      ["automations-row", CONTRACT_FIXTURES.automations[0], (REC.endpoints["automations"].body as { automations: Record<string, unknown>[] }).automations?.[0]],
      ["notes-row", CONTRACT_FIXTURES.notes[0], (REC.endpoints["notes"].body as { notes: Record<string, unknown>[] }).notes?.[0]],
      ["overview", CONTRACT_FIXTURES.overview, REC.endpoints["overview"].body],
      ["spend", CONTRACT_FIXTURES.spend, REC.endpoints["spend"].body],
    ];
    for (const [name, canned, live] of pairs) {
      if (live === undefined) continue;
      const ck = cannedKeys(canned);
      const lk = cannedKeys(live);
      if (ck !== lk) diffs.push(`  ${name}:\n    canned: ${ck}\n    live:   ${lk}`);
    }
    if (diffs.length > 0) {
      console.log(
        "fixtures-live: SHAPE-DIFF (canned fixture vs live wire — the V-24 fiction classes, made visible; " +
        "dual-lane pins admit both where receipted):\n" + diffs.join("\n"),
      );
    } else {
      console.log("fixtures-live: shape-diff — canned and live key sets match on every probed shape");
    }
    expect(true).toBe(true); // informational by design
  });
}
